import numpy as np

def feature(item, bins, capacity):
    """Fraction of each candidate bin's remaining capacity that the incoming item would fill."""
    return np.clip(item / np.maximum(bins, 1), 0.0, 1.0)

import numpy as np

def feature(item, bins, capacity):
    """Sharp Gaussian-like bonus peaking at 1 when a bin's remaining room exactly equals the item, decaying exponentially with mismatch scaled by 0.1*capacity."""
    scale = 0.1 * capacity
    return np.exp(-np.abs(bins - item) / scale)

import numpy as np


def feature(item, bins, capacity):
    """Percentile rank of each candidate's post-placement leftover among all candidates (1 = tightest, -1 = loosest), ties broken by the fuller bin (smaller remaining room)."""
    k = bins.shape[0]
    if k < 2:
        return np.zeros(k, dtype=float)
    left = np.clip(bins - item, 0, capacity)
    # Primary key: leftover (ascending); secondary key: current room (ascending, fuller bin first)
    order = np.lexsort((bins, left))
    rank = np.empty(k, dtype=float)
    rank[order] = np.arange(k, dtype=float)
    return 1.0 - 2.0 * rank / (k - 1)

import numpy as np

def feature(item, bins, capacity):
    """Normalised recency rank of each candidate: +1 for the oldest open bin, -1 for the newest (the fresh bin), letting the optimiser blend age (first-fit pressure) with fit quality."""
    k = len(bins)
    if k <= 1:
        return np.zeros(k, dtype=float)
    # idx 0 = oldest existing bin ... idx k-1 = brand-new empty bin (last entry)
    return 1.0 - 2.0 * (np.arange(k, dtype=float) + 0.5) / float(k)

import numpy as np

def feature(item, bins, capacity):
    """Balance: closeness of each candidate's post-placement leftover to the average leftover of the existing open bins (fragmentation balance)."""
    cap = float(max(capacity, 1))
    b = np.asarray(bins, dtype=float)
    leftover = np.clip(b - float(item), 0.0, cap)
    # centre on the typical leftover of the already-open bins (exclude the brand-new bin)
    if leftover.size > 1:
        centre = float(np.mean(leftover[:-1]))
    else:
        centre = float(leftover[-1])
    return -(np.abs(leftover - centre) / cap)

import numpy as np

def feature(item, bins, capacity):
    """Negative absolute rank position of the leftover (bins-item) among candidates, peaking at the median leftover."""
    L = np.asarray(bins, dtype=float) - float(item)
    k = L.shape[0]
    if k < 2:
        return np.zeros(k, dtype=float)
    order = np.argsort(L, kind='stable')
    ranks = np.empty(k, dtype=float)
    ranks[order] = np.arange(k, dtype=float)
    p = 2.0 * ranks / (k - 1) - 1.0
    return -np.abs(p)
